# coding: utf-8
"""Editorial layout; retains the complete audited evidence under disclosure panels."""
import re

def redesign(document):
    sections = dict(re.findall(r'<section id="([^"]+)">(.*?)</section>', document, re.S))
    def body(name):
        return re.sub(r'^<div class="num">.*?</div><h2>.*?</h2>', '', sections[name], count=1, flags=re.S)
    def panel(title, content, ident=''):
        return '<details class="deep"'+(' id="'+ident+'"' if ident else '')+'><summary>'+title+'</summary><div class="deep-body">'+content+'</div></details>'
    css = '''
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto!important}}
:root{--ink:#192d38;--accent:#176477;--line:#d9e0e2}body{background:#fafbfc;color:var(--ink);font-size:16px;line-height:1.8}main{max-width:1120px;padding:0 44px 72px}nav{background:#ffffffed;border-bottom:1px solid var(--line);padding:14px max(24px,calc((100vw - 1032px)/2));gap:26px;flex-wrap:nowrap;overflow:auto;white-space:nowrap}nav a{color:#405964;font-size:13px}nav a:hover{color:#176477}header{padding:42px 0 22px;border:0}h1{font-size:clamp(30px,3.5vw,45px);letter-spacing:-1px;line-height:1.3;margin:12px 0 10px}h2{font-size:28px;line-height:1.4;margin:8px 0 20px}h3{font-size:19px;margin:24px 0 10px}.eyebrow,.num{color:#58717e;letter-spacing:1.5px;font-size:11px}section{padding:44px 0;border-bottom:1px solid var(--line)}#timing{padding-top:8px}.answer{font-size:20px;line-height:1.75;max-width:850px;margin-bottom:24px}.answer b{color:#176477}.subtitle{color:#637580;margin:0;font-size:14px}.formula-board{background:#152f3a;color:white;padding:28px 30px;margin:16px 0 22px}.formula-title{font-size:12px;color:#b8cbd2;margin-bottom:12px}.equation{font-size:clamp(19px,2.3vw,28px);line-height:1.7;font-weight:500;overflow-wrap:normal}.equation .term{display:inline-block;white-space:nowrap}.equation small{font-size:14px;color:#c2d2d8}.term-row{display:grid;grid-template-columns:repeat(5,1fr);margin-top:24px;border-top:1px solid #ffffff30;padding-top:18px;gap:16px}.term-row b{display:block;font-size:27px;line-height:1.4}.term-row span{font-size:12px;color:#c2d2d8}.formula-foot{font-size:12px;color:#c2d2d8;margin:16px 0 0}.decisions{display:grid;grid-template-columns:repeat(3,1fr);gap:28px;margin:24px 0}.decisions article{border-top:2px solid #176477;padding-top:14px}.decisions h3{margin:0 0 8px;font-size:17px}.decisions p{font-size:14px;margin:0;color:#4f6571}.mechanism{padding:18px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);font-size:17px}.mechanism p{margin:5px 0}.kicker{font-size:12px;color:#176477;font-weight:700}.scene-grid{display:grid;grid-template-columns:1fr 1fr;gap:32px}.scene-grid>article{min-width:0}.scene-grid h3{margin-top:12px}.scene-grid figure img{aspect-ratio:auto;object-fit:contain;border-radius:0}.scene-grid p{font-size:15px}.verdict{border-left:3px solid #176477;padding:10px 16px;background:#eff5f7;margin:16px 0;font-size:15px}.baseline{padding:18px 22px;background:#eff5f7;line-height:1.9;margin-top:24px}.baseline strong{font-size:23px;color:#176477}.deep{border:0;border-top:1px solid var(--line);border-radius:0;background:transparent;padding:0;margin:20px 0 0}.deep>summary{padding:17px 0;font-size:14px;color:#365b6a}.deep-body{padding:8px 0 24px}.deep-body p{font-size:14px}.deep-body h3{font-size:19px}.deep-body .formula{font-size:13px}.scroll{margin:16px 0}th{background:#eef2f4;color:#365463}th,td{border-color:#e0e6e9;padding:12px;line-height:1.65}td{font-size:14px}.compact th:first-child{width:20%}.note{font-size:13px;color:#667985}.formula{border-radius:0;background:#203e4a}.callout{background:#f3f1e9;border-left-color:#ae8950}.contextsvg{background:#f0f4f6}.deep .stats{display:none}footer{border-top:1px solid var(--line);margin-top:25px}.jump{font-size:13px}.report-meta{display:flex;gap:16px;flex-wrap:wrap;font-size:12px;color:#687d88;margin-top:16px}@media(max-width:760px){main{padding:0 20px 45px}header{padding:28px 0 18px}nav{padding:12px 20px;gap:22px}section{padding:32px 0}h2{font-size:24px}.answer{font-size:18px}.formula-board{padding:22px 18px}.term-row{grid-template-columns:repeat(3,1fr);gap:15px}.term-row b{font-size:23px}.decisions,.scene-grid{grid-template-columns:1fr;gap:22px}.equation{font-size:20px}.scene-grid figure img{max-height:270px;object-fit:contain;background:#e8ecee}.mechanism{font-size:15px}}@media print{.deep:not([open]){display:none}.formula-board{print-color-adjust:exact;-webkit-print-color-adjust:exact}.scene-grid{grid-template-columns:1fr 1fr}nav{display:none}}
'''
    head = document[:document.index('<nav>')].replace('</style>', css+'</style>')
    head = head.replace('RPent 120 集：推理耗时与优化报告','RPent：耗时公式与三个性能问题')
    content = '''<nav aria-label="报告导航"><a href="#timing">耗时公式</a><a href="#prefill">01 · Prefill / Thinking</a><a href="#cases">02 · 轨迹与基线</a><a href="#io">03 · 输入与上下文</a><a href="#appendix">证据附录</a></nav><main>
<header id="overview"><div class="eyebrow">RPENT / 推理性能分析 / v2.0 · 2026-10-08</div><h1>先看耗时构成，再决定如何优化。</h1><p class="subtitle">120 集既有评测 · Astra / Sol 均为 medium · 以三个问题组织结论与证据</p></header>
<section id="timing"><div class="formula-board"><div class="formula-title">核心公式 · 每集互斥记账，120 集逐项对账〔E2〕</div><div class="equation">T<sub>episode</sub> = T<sub>非π动作</sub> + T<sub>π 动作</sub> + T<sub>工具附加</sub><br> + T<sub>SDK 未覆盖时段</sub> + T<sub>外壳</sub></div><div class="term-row"><div><b>36.7%</b><span>非 π 动作原语</span></div><div><b>7.6%</b><span>π0.5 动作原语</span></div><div><b>10.1%</b><span>工具附加开销</span></div><div><b>43.3%</b><span>SDK 未覆盖时段</span></div><div><b>2.3%</b><span>SDK 外壳开销</span></div></div><p class="formula-foot">分母：120 集 episode 耗时之和 34.28 h。VLA 模型加载日志段 5.78 h 另计；两者都不是并行运行的日历时长。</p></div>
<p><b>优化依据：</b>动作执行合计占 <b>44.3%</b>；另有 <b>43.3%</b> 尚未分清模型计算、网络、重试和编排。前者应查重复动作与仿真执行链，后者应先补测，再决定优化哪一段。</p>
<p class="note">非 π 动作指 move_to / move_pose / 夹爪等脚本原语，并非人工接管；包含控制与环境 step；π 动作还包含模型前向。两者都可能包含步内观测渲染。工具附加是工具区间扣除动作后的残差；SDK 未覆盖是 SDK 扣除已完成 MCP 工具区间后的残差，<b>不能等同于 thinking</b>。</p>
<div id="opt" class="mechanism"><div class="kicker">从账本到优化变量 · 以下是待打点的结构模型〔E3〕</div><p>T<sub>episode</sub> ≈ N<sub>模型请求</sub> × 平均模型请求时延 + T<sub>动作与工具</sub> + T<sub>编排与外壳</sub></p><p>单次请求耗时 ≈ 上传 / 排队 / 预处理 + <b>prefill + thinking + 可见输出</b> + 下载 / 重试</p><p class="note">串行近似：模型请求时延不含工具执行；N 为真实模型请求数，5,014 只是有用量的计量响应数。不能与五桶重复相加，实际调度可能重叠。优化有两条主线：减少不必要的请求与动作，降低必要步骤的单位成本。</p></div>
<div class="decisions"><article><h3>先测清：43.3% 的残差</h3><p>本地可补请求与工具边界。真正云端 prefill / thinking 分界需服务端遥测，本地无法直接控制其内核与排队。</p></article><article><h3>优先验证：44.3% 的动作链</h3><p>减少无进展抓取、到不了的目标点与重复感知；定位 step、渲染、RPC 成本。优化须保持成功率和判分。</p></article><article><h3>之后再做：π 单点加速</h3><p>π 动作整桶只占 7.6%。固定轨迹时，即使整桶归零，总体上限也仅 1.082×；纯网络加速收益更小。〔E3〕</p></article></div>
'''
    content = re.sub(r'T<sub>([^<]+)</sub>', r'<span class="term">T<sub>\1</sub></span>', content)
    content += panel('查看公式定义、各模型 / 套件占比与内部耗时拆分', body('timing'))+'</section>'
    content += '''<section id="prefill"><div class="num">问题 01 / PREFILL 与 THINKING</div><h2>能否拆分？历史记录不能精确拆，重跑也需要服务端配合。</h2><p class="answer">本批能准确对账的是<b>端到端、工具区间和 SDK 残差</b>；没有云端 prefill 与完整 hidden thinking 的独立计时。把首输出等待或 43.3% 残差直接称为 thinking，会得出错误的优化方向。</p><div class="scroll"><table><thead><tr><th>想知道的量</th><th>现在能回答什么</th><th>补测后能多知道什么</th></tr></thead><tbody><tr><td>Prefill 耗时</td><td>未采集；Token 数、缓存率不能换算成秒。</td><td>客户端可测 TTFT；真实 prefill 仍需服务端阶段时间。</td></tr><tr><td>完整 thinking 耗时</td><td>未采集；可见 reasoning 事件不是完整计算时间。</td><td>客户端事件可更完整，仍不能替代 hidden reasoning 遥测。</td></tr><tr><td>π / SAM3 / 仿真耗时</td><td>仅有动作原语、工具边界；纯 forward、physics、render 未分开。</td><td>可在本地增加同步打点，分别测 forward、step、render、RPC。</td></tr></tbody></table></div><div class="verdict"><b>对优化的含义：</b>先做小规模性能探针，不以“缩短 prompt = prefill 必然按比例变快”为前提。客户端时间用 monotonic 时钟；NPU 前向需同步测量并检查 profiler 本身的扰动。〔E3〕</div>'''
    content += panel('测到了哪些事件、如何计数，以及补测方案', body('prefill'))+'</section>'
    # Reuse two real frames, not ornamental stock images.
    imgs = re.findall(r'<figure>.*?</figure>', sections['cases'], re.S)
    content += '''<section id="cases"><div class="num">问题 02 / 冗余尝试、推理轮次与性能基线</div><h2>成功路径查冗余，失败路径查无进展重试。</h2><p class="answer">选择 <b>Long Swap t0“双罐入篮”</b>和 <b>t9“杯子入微波炉并关门”</b>：各含 Astra / Sol × seed0/1，共 8 集。t0 全成功，t9 全失败；两者用于解释机制，不代表三个套件的全部任务。</p><div class="scene-grid"><article>'''+imgs[3]+'''<h3>A · 双罐入篮 / t0</h3><p><b>实测：</b>39–50 条计量响应；最快成功 Astra seed1，42 条响应、940.5 秒。</p><p><b>冗余证据：</b>Astra seed0 一次抓取抬升为零，8 chunks 耗时 25.37 秒；又用 4 chunks 才通过判据。放置时还有目标未到位后的修正。</p><p><b>理想闭环计划：</b>读取与定位 → 第一罐抓取、确认、放置 → 第二罐抓取、确认、放置 → 终止确认。按阶段合并，可提出 <b>10 个决策节点</b>。〔E3〕</p></article><article>'''+imgs[7]+'''<h3>B · 杯子入微波炉 / t9</h3><p><b>实测：</b>56–86 条计量响应；4/4 失败，没有成功耗时基线。</p><p><b>重复证据：</b>Sol seed1 前五次抓取均未通过判据，共 <b>74 chunks / 213.26 秒</b>；后来改抓杯沿，27.46 秒通过抓取判据，最终仍未完成任务。</p><p><b>理想闭环计划：</b>定位 → 开门与确认 → 抓取与确认 → 搬运对齐 → 插入、确认与释放 → 关门与终止确认。可提出 <b>12 个决策节点</b>。〔E3〕</p></article></div>
<div class="verdict"><b>10 / 12 不是已证明的最少推理次数。</b>它们要求感知可批量、局部控制可靠、首次抓取成功且无需恢复。一次模型响应可以含多个工具调用；一个 π 工具又可以含多个 chunk。三种次数不能混用。工具返回 false 也不总等于无效动作。〔E2/E3〕</div>
<div class="baseline"><div class="kicker">成功场景的条件估算 · Astra t0 / seed1</div><p>实测：940.5 s = 578.198 s 工具 + 340.402 s SDK 残差 + 21.9 s 外壳</p><p>若工具路径不变、残差按计量响应数线性缩放，42 → 10 条响应：</p><strong>578.198 + 21.9 + 10 × (340.402 / 42) ≈ 681.15 s</strong><p class="note">约减少 27.6%，是未实测的情景估算；8.10 s 只是每响应分摊的残差，不是单次 thinking。微波炉场景不填虚构的最佳成功秒数。〔E3〕</p></div>'''
    content += panel('查看 8 集对照、录像关键帧与逐动作证据', body('cases'))
    content += panel('查看完整 10 / 12 节点计划、收益假设及 GPT-as-Policy 对照', body('opt'))+'</section>'
    content += '''<section id="io"><div class="num">问题 03 / 输入输出、PROMPT 与上下文</div><h2>三类模型的输入不同；Astra 当前输入也不等于累计 Token。</h2><div class="scroll compact"><table><thead><tr><th>模块</th><th>实际输入</th><th>实际输出</th><th>上下文口径</th></tr></thead><tbody><tr><td><b>π0.5</b></td><td>主 / 腕两图 256²、8 维机器人状态、当前子任务指令。</td><td>返回 [5,7] 动作块，最多执行 5 个控制步；每步含位置、旋转与夹爪。</td><td>当前观测；文本槽上限 200，非实测 Token 数。不接收完整 Astra 对话。</td></tr><tr><td><b>SAM3</b><br>用户所称 sim3</td><td>所选图像 + 文本提示或像素点 + 阈值。</td><td>mask / box / score；world_xyz 由工具结合深度反投影。</td><td>无聊天历史；缓存最近图像的编码特征。</td></tr><tr><td><b>Astra / Sol</b></td><td>基础与 developer 指令、RPent 任务 prompt、工具 Schema、记忆、历次工具结果与图像。</td><td>助手文本、可见 reasoning 事件、工具名与参数、finish。</td><td>对话随任务增长；每次 usage.input_tokens 是该次输入计量。</td></tr></tbody></table></div>
<h3>Astra 到底带了哪些 prompt？</h3><p>案例会话中：基础指令 <b>21,420 字符</b>；权限 / 角色 / 模式三类 developer 消息共 <b>3,982 字符</b>；环境上下文 <b>513 字符</b>；初始 RPent 任务消息 <b>33,744 字符</b>，包含角色、任务、记忆策略、定位流程、规则与输出要求。另有工具定义和不断追加的执行历史。<b>字符数不能直接相加当作 Token 数。</b>〔E2〕</p>
<h3>每次输入长度与上下文是否对应？</h3><p class="answer"><b>能与逐次用量计数对应，不能逐字段还原完整 HTTP payload。</b>120 集的逐响应 Token 加总均与该集总用量一致；这证明计量对账，不证明每个 prompt、图片和 Schema 的 Token 贡献已知。</p><div class="scroll"><table><thead><tr><th>Astra · t0 / seed1</th><th>第 1 次响应</th><th>第 20 次响应</th><th>第 42 次响应</th></tr></thead><tbody><tr><td>当前 input_tokens</td><td>18,869</td><td>90,218</td><td>136,173</td></tr><tr><td>其中 cached_input_tokens</td><td>8,960</td><td>89,984</td><td>135,936</td></tr></tbody></table></div><p class="note">全批 Astra 输入中位数 65,992.5 Token，缓存输入加权占比 96.08%。累计输入会反复计入历史前缀，并不是某一次上下文窗口的大小；高缓存率也不意味着 prefill 时间为零。〔E2〕</p>'''
    content += panel('查看所有 I/O 字段、工具 Schema、源码引用与逐次上下文曲线', body('io'))+'</section>'
    content += '<section id="appendix"><div class="num">附录 / 按需查证</div><h2>保留完整证据，让主线只回答三个问题。</h2><p class="note">计量响应共 5,014 条，不包含未返回用量的错误请求。原始 120 集结果不变，本轮只修改报告组织与展示。</p>'
    content += panel('A · 120 集逐集耗时、筛选与 CSV 导出', body('ledger'), 'ledger')
    content += panel('B · 来源、验收记录、20 份源码摘录与证据边界', body('evidence'), 'evidence')
    content += '</section><footer>RPent 推理性能分析 · v2.0 · 2026-10-08<br>主文：公式 + 三个答案。展开附录可查看完整证据；HTML 支持离线筛选与 CSV 导出。E1=源码，E2=记录，E3=条件推导。</footer></main>'
    scripts = document[document.index('<script id="data"'):]
    scripts = scripts.replace("behavior:'smooth'", "behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'")
    scripts = scripts.replace('</script></html>', '''</script><script>
function revealHash(){const el=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(!el)return;let p=el;while(p){if(p.tagName==='DETAILS')p.open=true;p=p.parentElement;}requestAnimationFrame(()=>el.scrollIntoView());}
window.addEventListener('hashchange',revealHash);if(location.hash)revealHash();
let printState=[];
window.addEventListener('beforeprint',()=>{printState=[...document.querySelectorAll('details')].map(d=>[d,d.open]);printState.forEach(([d])=>d.open=true);});
window.addEventListener('afterprint',()=>printState.forEach(([d,open])=>d.open=open));
</script></html>''')
    return head+content+scripts
